/* Employee time integrity: shared Oman-duty normalization.
   Raw timestamps remain untouched for audit. Calculations clamp to workshop duty
   windows (08:00-13:00, 15:00-19:00 Asia/Muscat); Friday is excluded. */
function woOmanParts(ms){const d=new Date(Number(ms));if(Number.isNaN(d.getTime()))return null;const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Muscat',weekday:'short',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d),o={};p.forEach(x=>{if(x.type!=='literal')o[x.type]=x.value});return o}
function woOmanWallMs(ms){const p=woOmanParts(ms);if(!p)return NaN;return Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)}
function woNormalDutyMinutes(start,end){start=Number(start);end=Number(end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return 0;let cur=start,total=0,guard=0;while(cur<end&&guard++<40){const p=woOmanParts(cur);if(!p)break;const day0=Date.UTC(+p.year,+p.month-1,+p.day),wallStart=woOmanWallMs(cur),wallEnd=woOmanWallMs(end);if(p.weekday!=='Fri'){for(const [a,b] of [[8,13],[15,19]]){const lo=day0+a*3600000,hi=day0+b*3600000;total+=Math.max(0,Math.min(wallEnd,hi)-Math.max(wallStart,lo))/60000}}const nextWall=day0+86400000;const delta=Math.max(60000,nextWall-wallStart);cur=Math.min(end,cur+delta)}return Math.max(0,total)}
