window.zukaitTimeEventIntegrity=function(events){const a=(Array.isArray(events)?events:[]).slice().sort((x,y)=>Number(x?.at||x?.start||0)-Number(y?.at||y?.start||0));let open=false;return a.map(e=>{const action=String(e?.action||e?.type||'').toUpperCase(),resume=action==='RESUME',start=action==='START',pause=action==='PAUSE',finish=action==='FINISH'||action==='STOP',orphanResume=resume&&!open;if(start||resume)open=true;if(pause||finish)open=false;return Object.assign({},e,{orphanResume})})};
function overdueDate(value){const raw=String(value??'').trim(),n=/^\d+(?:\.\d+)?$/.test(raw)?Number(raw):Date.parse(raw);if(!Number.isFinite(n)||!n)return '—';try{return new Date(n).toLocaleString('en-GB',{timeZone:'Asia/Muscat',hour12:true})}catch(_){return '—'}}
