function overdueTimeHistory(){if(role()!=='Manager')return;const history=(Array.isArray(stateNow().overdueTimeReviews)?stateNow().overdueTimeReviews:[]).slice().sort((a,b)=>Number(b.reviewedAt||0)-Number(a.reviewedAt||0));shell('Overdue Time Review History',history.length?history.map(x=>'<div class="wo-row"><div><b>JC '+esc(x.job||'—')+' · '+esc(x.employeeName||x.employeeId||'Unknown employee')+'</b><span>Reviewed by '+esc(x.reviewerName||x.reviewedBy||'Manager')+' · '+esc(overdueDate(x.reviewedAt))+'</span></div><b>Exceeded '+esc(woMins(Number(x.exceededMinutes)||0))+'</b></div>').join(''):'<p class="muted">No Overdue Time reviews have been confirmed yet.</p>')}
