// Counts and details use the same records and the workshop's calendar day.
function workshopDay(value=Date.now()){
 if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value;
 if(value==null||value==='')return '';
 const n=typeof value==='number'?value:Number(value)||Date.parse(value);
 if(!Number.isFinite(n))return '';
 return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Muscat',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(n));
}
function quickData(st,people,statuses,now=Date.now()){
 const day=workshopDay(now),active=(st.assign||[]).filter(a=>a&&!a.cancelled&&!a.completed&&norm(a.job)!=='id001');
 const leave=(st.leaves||[]).filter(l=>l&&!l.cancelled&&workshopDay(l.date)===day);
 const leaveIds=new Set(leave.map(l=>String(l.emp)));
 const open=(st.jobs||[]).filter(j=>j&&j.no&&norm(j.no)!=='id001'&&!j.deleted&&!j.delivered&&!j.archived&&!j.completed&&!['completed','closed','cancelled','delivered'].includes(String(j.status||'').toLowerCase()));
 const runningIds=statuses===null?null:new Set(statuses.filter(s=>['Working','Overtime'].includes(s.status)).map(s=>norm(s.job||s.assignment?.job||s.session?.job)));
 const running=runningIds===null?null:open.filter(j=>runningIds.has(norm(j.no)));
 const today=list=>(list||[]).filter(x=>x&&!x.voided&&!x.deleted&&!x.cancelled&&workshopDay(x.createdAt)===day).sort((a,b)=>(Number(b.createdAt)||Date.parse(b.createdAt)||0)-(Number(a.createdAt)||Date.parse(a.createdAt)||0));
 return {idle:null,running,leave:leave.filter((l,i)=>leave.findIndex(x=>String(x.emp)===String(l.emp))===i),consumables:today(st.consumables?.issues),paint:today(st.paintPurchasing?.orders)};
}
