let scheduled=false;const schedule=()=>{if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;ensurePanel();if(document.getElementById('v273TimeAttentionTile')?.style.display!=='none')window.v273SettleTimeAttention?.();installVoiceReview()},0)};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});schedule();ensureFloatingJobSearch();setInterval(()=>{ensurePanel();ensureFloatingJobSearch();if(role()==='Manager'){const box=document.getElementById('woDailySummary');if(box){const html=summaryHtml();if(box.innerHTML!==html)box.innerHTML=html;removeManagerSummaryReady();window.v273SettleTimeAttention?.()}}if(role()==='Supervisor'){document.querySelectorAll('[data-v143-unassigned-count]').forEach(b=>{const value=String(queue().length);if(b.textContent!==value)b.textContent=value})}},5000);
// Dashboard/report links are purpose-specific. Full review is entered only by top-search results.
function focusedDetail(no,scope='work'){
 fullReviewJob='';
 if(!['Manager','Supervisor'].includes(role()))return;
 const j=jobs().find(x=>norm(x.no)===norm(no));if(!j)return;
 const st=stateNow(),people=typeof users==='undefined'?[]:users,person=id=>people.find(u=>String(u.id)===String(id))?.name||id||'—';
 const titles={work:'Work Details',running:'Running Work',completed:'Completed Work',repeat:'Repeat Work',assignments:'Assignments',attention:'Work Attention',cash:'Cash Details',delivery:'Delivery Details'};
 const title=titles[scope]||titles.work;
 let aa=(st.assign||[]).filter(a=>a&&!a.cancelled&&norm(a.job)===norm(no));
 if(scope==='running')aa=aa.filter(a=>!a.completed);
 if(scope==='completed')aa=aa.filter(a=>a.completed);
 if(scope==='repeat')aa=aa.filter(a=>a.rework);
 let body='<div class="wo-focus-identity"><b>JC '+esc(j.no)+'</b><span>'+esc(j.vehicle||'Vehicle')+' · '+esc(j.reg||'—')+'</span></div>';
 if(scope==='cash'){
  const invoice=j.finalInvoiceAmount??j.invoiceAmount;
  body+='<div class="wo-stats"><b>Cash Amount · OMR '+Number(j.amount||0).toFixed(3)+'</b><b>Status · '+(j.delivered?'Delivered':'Not delivered')+'</b>'+(invoice!=null?'<b>Final Invoice · OMR '+Number(invoice).toFixed(3)+'</b>':'')+'</div><p>Received · '+esc(overdueDate(j.createdAt))+'</p>'+(j.delivered?'<p>Delivered · '+esc(overdueDate(j.deliveredAt))+'</p>':'')+(j.invoiceDate?'<p>Invoice date · '+esc(j.invoiceDate)+'</p>':'');
 }else if(scope==='delivery'){
  const qc=j.qcWorkflow||{};
  body+='<p>Painting QC · '+esc(qc.painting?.result||'Pending')+'</p><p>Final QC · '+esc(qc.final?.result||'Pending')+'</p><p>Delivery · '+(j.delivered?esc(overdueDate(j.deliveredAt)):'Pending')+'</p>';
 }else{
  if(scope==='attention'){
   const entry=window.v273RunningAttentionRows?.().find(x=>norm(x.job?.no)===norm(no));
   body+=(entry?.items||[]).map(x=>'<div class="notice"><b>'+esc(x.a?person(x.a.emp):'Unassigned')+'</b><p>'+(x.reasons||[]).map(esc).join('<br>')+'</p></div>').join('');
   aa=aa.filter(a=>!a.completed);
  }
  body+=aa.length?aa.map(a=>{let status=a.completed?'Completed':'Assigned';try{if(typeof empStatus==='function')status=empStatus(a)}catch(_){}return '<article class="wo-quick-detail"><b>'+esc(person(a.emp))+'</b><p>'+esc(status)+(a.rework?' · Repeat work':'')+'</p><p>Suggested · '+esc(woMins(a.suggested))+'<br>Actual · '+esc(woMins(woActual(a)))+'</p>'+(a.rework&&a.reason?'<p>Reason · '+esc(a.reason)+'</p>':'')+(scope==='assignments'&&role()==='Supervisor'&&!a.completed?'<button type="button" data-workshop-action="focused-assignment" data-assignment="'+esc(a.id)+'">Assignment Actions</button>':'')+'</article>'}).join(''):'<p>No '+(scope==='completed'?'completed work':scope==='repeat'?'repeat work':'matching assignments')+' for this job card.</p>';
  if(scope==='assignments'&&role()==='Supervisor'&&!aa.length&&!j.delivered)body+=button('Assign Technician','assign',j.no);
 }
 shell(title, '<div class="wo-focused-job" data-job-scope="'+esc(scope)+'">'+body+'</div>');
}
window.zukaitOpenFocusedJob=focusedDetail;
window.zukaitOpenWorkDetails=no=>focusedDetail(no,'work');
window.zukaitOpenRunningDetails=no=>focusedDetail(no,'running');
window.zukaitOpenCompletedDetails=no=>focusedDetail(no,'completed');
window.zukaitOpenRepeatDetails=no=>focusedDetail(no,'repeat');
window.zukaitOpenAttentionDetails=no=>focusedDetail(no,'attention');
window.zukaitOpenCashDetails=no=>focusedDetail(no,'cash');
window.zukaitOpenDeliveryDetails=no=>focusedDetail(no,'delivery');
// Compatibility names deliberately cannot open the complete review.
window.zukaitOpenJob360=window.zukaitOpenWorkDetails;
window.zukaitOpenJobReview360=window.zukaitOpenWorkDetails;
window.openManagerJobDetails=window.zukaitOpenWorkDetails;
window.v68OpenJobDetail=window.zukaitOpenWorkDetails;
window.openSupervisorJob=no=>focusedDetail(no,'assignments');
window.v132OpenSupervisorJobFull=no=>focusedDetail(no,'assignments');
window.zukaitJob360Ready=true;
